// GradientBackground — "Spinny thing", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=8390de08-b510-4c99-9113-249f43ec4da3
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: "-3.4cqmin",
        filter: "blur(1.7cqmin)",
        backgroundColor: "#2F51C1",
        backgroundImage:
          "radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0) 52%, rgba(0, 0, 0, 0.336) 100%), conic-gradient(from 142deg at 50% 50%, #2F51C1 32%, #6500B8 35%, #DD2C2C 41%, #DC2C2C 58%, #530097 75%, #123A6B 90%)",
        }}
      />
    </div>
  )
}

